package com.oms.order.service;

import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.*;

class ExchangeFlowAutomationTest {
    ExchangeServiceTest f;JdbcTemplate db;ExchangeFlowPolicy policies;ExchangeAutomaticDecision decisions;ExchangeOperationJournal journal;
    Map<String,Object> policy;
    @BeforeAll static void database(){ExchangeServiceTest.start();}
    @BeforeEach void setup() throws Exception {
        f=new ExchangeServiceTest();f.reset();db=ExchangeServiceTest.db;
        for(String t:Arrays.asList("oms_exchange_operation","oms_exchange_flow_task","oms_exchange_flow_policy","oms_refund"))db.update("DELETE FROM "+t+" WHERE company_code='VERIFY'");
        when(f.catalog.goods(anyString(),anyList())).thenAnswer(a->{Map<String,List<Map<String,Object>>> goods=new HashMap<>();for(Object sku:(List<?>)a.getArgument(1))goods.put(String.valueOf(sku),Collections.singletonList(map("sku_sn",sku,"goods_name",sku,"is_fd",0,"is_package",0)));return goods;});
        ObjectNode root=(ObjectNode)JSON.readTree(f.original);ObjectNode trade=(ObjectNode)root.path("trade_fullinfo_get_response").path("trade");trade.put("receiver_name","test");trade.put("receiver_mobile","TEST");trade.put("receiver_state","北京市");trade.put("receiver_city","北京市");trade.put("receiver_address","test address");f.original=JSON.writeValueAsString(root);db.update("UPDATE oms_platform_order SET raw_payload=?,processing_payload=?,payload_hash=? WHERE id=?",f.original,f.original,hash(f.original),f.platform);
        policies=new ExchangeFlowPolicy();policies.repository=f.repo;policies.catalog=f.catalog;ReflectionTestUtils.setField(f.service,"automaticPolicies",policies);
        policy=ExchangeFlowPolicy.defaults();for(String key:ExchangeFlowPolicy.FLAGS)policy.put(key,1);policy.putAll(map("enabled",1,"revision",0,"quantity_limit",5,"return_store","V1","platform_address_id","99","return_address","test return address","return_contact","test contact","mappings",Arrays.asList(mapping("A","Blue / L","B"),mapping("A","B","B"),mapping("B","A","A"))));policies.save("VERIFY",1,policy,"merchant authorization");policy=policies.read("VERIFY",1);
        decisions=new ExchangeAutomaticDecision();decisions.repository=f.repo;decisions.exchanges=f.service;decisions.policies=policies;decisions.continuations=mock(ExchangeContinuationService.class);
        journal=new ExchangeOperationJournal();journal.repository=f.repo;journal.policies=policies;
    }
    @AfterEach void clear(){for(String t:Arrays.asList("oms_exchange_operation","oms_exchange_flow_task","oms_exchange_flow_policy"))db.update("DELETE FROM "+t+" WHERE company_code='VERIFY'");}
    Map<String,Object> mapping(String from,String target,String sku){return map("source_sku",from,"platform_target",target,"target_sku",sku,"no_surcharge_basis","merchant authorized same-price exchange rule");}
    long source(){Map<String,Object> source=f.source();source.put("refund_phase","after_sale");return f.ingest(source);}
    Map<String,Object> row(long id){return f.service.row("VERIFY",id,false);}
    void decide(long id){decisions.decide("VERIFY",row(id),policy);}
    ExchangeFlowAutomation flow(){ExchangeFlowAutomation flow=new ExchangeFlowAutomation();flow.repository=f.repo;flow.exchanges=f.service;flow.policies=policies;flow.decisions=decisions;flow.execution=mock(ExchangeExecution.class);flow.fulfillment=mock(ExchangeFulfillment.class);when(flow.fulfillment.reserve(anyString(),anyLong())).thenReturn(true);flow.returns=mock(ExchangeAutoReturns.class);flow.shipping=mock(ExchangeAutomaticFulfillment.class);flow.journal=journal;flow.stop=mock(ExchangeFlowStop.class);return flow;}
    void task(long id){db.update("INSERT INTO oms_exchange_flow_task(company_code,exchange_id) VALUES ('VERIFY',?)",id);}

    @Test void exactMappingAutomaticallyReviewsWithSeparateSystemActor(){long id=source();decide(id);Map<String,Object> e=row(id);assertEquals("APPROVED",e.get("state"));assertEquals("B",e.get("target_sku"));assertEquals(ExchangeFlowPolicy.REVIEW_ACTOR,e.get("review_by"));Map<String,Object> snapshot=object(e.get("approved_snapshot"));assertEquals(1,number(snapshot,"automatic_policy_revision"));assertEquals("O",object(snapshot.get("return_basis")).get("owner_code"));assertEquals("merchant authorized same-price exchange rule",object(snapshot.get("automatic_authorization")).get("no_surcharge_basis"));assertNull(e.get("stock_request"));}
    @Test void similarTargetDescriptionDoesNotGuessSku(){Map<String,Object> source=f.source();source.put("exchange_sku","Blue L similar");long id=f.ingest(source);assertThrows(IllegalArgumentException.class,()->decide(id));assertNull(row(id).get("approved_version"));}
    @Test void exactQuantityLimitPreservesOriginalApplication(){long id=source();policy.put("quantity_limit",1);assertThrows(IllegalArgumentException.class,()->decide(id));assertEquals(2,number(row(id),"requested_quantity"));assertNull(row(id).get("approved_version"));}
    @Test void buyerAddressChangeCannotUseOriginalAddressAuthorization(){Map<String,Object> source=f.source();source.put("buyer_address","different address");long id=f.ingest(source);assertThrows(IllegalArgumentException.class,()->decide(id));assertNull(row(id).get("approved_version"));}
    @Test void internalExchangeWithoutExplicitBusinessAuthorizationRemainsManual(){long id=f.createNegotiated(2,"AUTO_INTERNAL_MISSING");assertThrows(IllegalArgumentException.class,()->decide(id));assertNull(row(id).get("approved_version"));}
    @Test void explicitlyAuthorizedNegotiatedSourceIsAutomaticallyReviewed(){Map<String,Object> input=f.negotiated(2,"AUTO_INTERNAL_ALLOWED");input.put("automation_authorized",true);input.put("authorization_reference","MERCHANT-CASE-001");long id=number(f.fulfillment().create("VERIFY",input,"merchant"),"id");decide(id);assertEquals(ExchangeFlowPolicy.REVIEW_ACTOR,row(id).get("review_by"));assertEquals("RETURN",row(id).get("fulfillment_mode"));}
    @Test void unshippedReplacementRequiresBusinessAuthorizationAndRecordsAutomaticReview(){db.update("UPDATE oms_order_shipment_line SET shipped_quantity=0 WHERE shipment_id=?",f.shipment);Map<String,Object> input=f.negotiated(2,"AUTO_UNSHIPPED_ALLOWED");input.put("fulfillment_mode","UNSHIPPED");input.put("source_phase","DURING_SALE");input.put("automation_authorized",true);input.put("authorization_reference","MERCHANT-UNSHIPPED-001");long id=number(f.fulfillment().create("VERIFY",input,"merchant"),"id");decide(id);assertEquals(ExchangeFlowPolicy.REVIEW_ACTOR,row(id).get("review_by"));assertEquals("WITHDRAW",row(id).get("stage"));assertNull(row(id).get("fulfillment_line_id"));assertNull(row(id).get("stock_request"));}
    @Test void enabledAutomationStillRequiresNodeAuthorization(){long id=source();Map<String,Object> changed=new LinkedHashMap<>(policy);changed.put("auto_review",0);policies.save("VERIFY",1,changed,"merchant");assertThrows(IllegalArgumentException.class,()->decide(id));assertNull(row(id).get("approved_version"));}
    @Test void duplicateAutomaticIntentReusesOneCommandAndOriginalRequestId(){long id=source();decide(id);Map<String,Object> first=journal.begin("VERIFY",row(id),"AGREE",policy,map("operation","AGREE"));Map<String,Object> again=journal.begin("VERIFY",row(id),"AGREE",policy,map("operation","AGREE"));assertEquals(first.get("id"),again.get("id"));assertEquals(first.get("request_id"),again.get("request_id"));journal.update("VERIFY",number(first,"id"),"UNKNOWN","timeout",null);assertThrows(IllegalArgumentException.class,()->{Map<String,Object> changed=new LinkedHashMap<>(policy);changed.put("enabled",0);policies.save("VERIFY",1,changed,"merchant");journal.authorize("VERIFY",row(id),map("flow_operation_id",first.get("id"),"operation","AGREE"));});}
    @Test void unknownPlatformOperationIsReconciledEvenWhenRulesDisabled(){long id=source();task(id);db.update("UPDATE oms_exchange SET platform_operation='UNKNOWN' WHERE id=?",id);db.update("UPDATE oms_exchange_flow_policy SET enabled=0 WHERE company_code='VERIFY'");ExchangeFlowAutomation flow=flow();assertEquals("WAITING",flow.step("VERIFY",id,1).get("state"));verify(flow.execution).process("VERIFY",id);verifyNoInteractions(flow.fulfillment,flow.returns,flow.shipping);}
    @Test void staleNotificationsDoNotReadOrConsumePlatformQuota(){long id=source();task(id);db.update("UPDATE oms_exchange_flow_task SET work_version=2 WHERE exchange_id=?",id);ExchangeFlowMessage message=new ExchangeFlowMessage();message.flow=flow();message.platform=mock(ExchangePlatformClient.class);assertTrue(message.rateKeys("VERIFY",map("business_id",id,"business_version",1)).isEmpty());verifyNoInteractions(message.platform);}
    @Test void receiptAndWarehouseWaitsDoNotConsumePlatformQuota(){assertFalse(ExchangeFlowMessage.platformWork(map("source_kind","PLATFORM","platform_operation","NONE","platform_status","3")));assertFalse(ExchangeFlowMessage.platformWork(map("source_kind","INTERNAL","platform_operation","NONE")));assertTrue(ExchangeFlowMessage.platformWork(map("source_kind","PLATFORM","platform_operation","PENDING","platform_status","3")));assertTrue(ExchangeFlowMessage.platformWork(map("source_kind","PLATFORM","platform_operation","NONE","platform_status","13")));}
    @Test void staleMessageDoesNotAdvanceAnyBusinessNode(){long id=source();task(id);db.update("UPDATE oms_exchange_flow_task SET work_version=2 WHERE exchange_id=?",id);ExchangeFlowAutomation flow=flow();assertEquals("DONE",flow.step("VERIFY",id,1).get("state"));verifyNoInteractions(flow.execution,flow.fulfillment,flow.returns,flow.shipping);}
    @Test void fullLogicalReservationIsNotRegisteredAgainWhileWaitingForReceipt(){long id=source();decide(id);task(id);db.update("UPDATE oms_exchange SET platform_status='3',stock_request='{}',stock_receipt='{\"reserved_quantity\":2}' WHERE id=?",id);ExchangeFlowAutomation flow=flow();when(flow.returns.advance(anyString(),anyMap(),anyMap())).thenReturn(map("posted_quantity",0,"receipt_state","WAITING","dispatch_state","ACCEPTED"));assertEquals("WAIT_RETURN",flow.step("VERIFY",id,1).get("code"));verifyNoInteractions(flow.fulfillment);}
    @Test void badGoodsAndUnallocatedReceiptsCannotAutomaticallyPassQc(){long id=source();decide(id);task(id);db.update("UPDATE oms_exchange SET platform_status='3',return_sn='THX_AUTO' WHERE id=?",id);ExchangeFlowAutomation flow=flow();when(flow.returns.advance(anyString(),anyMap(),anyMap())).thenReturn(map("posted_quantity",2,"receipt_state","COMPLETED","grades",map("good_qty",1,"bad_qty",1,"posted_qty",2)));assertEquals("MANUAL",flow.step("VERIFY",id,1).get("state"));verify(flow.execution,never()).qc(anyString(),anyLong(),anyMap(),anyString());verifyNoInteractions(flow.shipping);}
    @Test void completeGoodReceiptAutomaticallyConfirmsQcWithoutStockMutation(){long id=source();decide(id);task(id);db.update("UPDATE oms_exchange SET platform_status='3',return_sn='THX_AUTO' WHERE id=?",id);ExchangeFlowAutomation flow=flow();when(flow.returns.advance(anyString(),anyMap(),anyMap())).thenReturn(map("posted_quantity",2,"receipt_state","COMPLETED","grades",map("good_qty",2,"bad_qty",0,"posted_qty",2)));assertEquals("QC_PASSED",flow.step("VERIFY",id,1).get("code"));verify(flow.execution).qc(eq("VERIFY"),eq(id),argThat(m->"PASSED".equals(m.get("decision"))),eq(ExchangeFlowPolicy.ACTOR));verifyNoInteractions(flow.shipping);}
    @Test void sharedRefundPostingWaitsWithoutManualReviewAndResumesOnlyAfterGateClears(){
        long id=source();decide(id);task(id);db.update("UPDATE oms_exchange SET platform_status='12',return_qc='PASSED' WHERE id=?",id);
        db.update("UPDATE oms_order_line SET refund_block_reason='平台退款 TEST 的本子单商品待审核或货物处理' WHERE order_id=?",f.order);
        ExchangeFlowAutomation flow=flow();when(flow.returns.advance(anyString(),anyMap(),anyMap())).thenReturn(map("posted_quantity",2,"receipt_state","COMPLETED"));
        assertEquals("WAIT_REFUND",flow.step("VERIFY",id,1).get("code"));verifyNoInteractions(flow.shipping);
        db.update("UPDATE oms_order_line SET refund_block_reason='' WHERE order_id=?",f.order);
        when(flow.shipping.advance(anyString(),anyMap(),anyMap(),eq(1L))).thenReturn(map("state","WAITING","code","WAIT_ACTUAL_OUTBOUND"));
        assertEquals("WAIT_ACTUAL_OUTBOUND",flow.step("VERIFY",id,1).get("code"));verify(flow.shipping).advance(eq("VERIFY"),anyMap(),anyMap(),eq(1L));
    }
    @Test void unresolvedRefundGateHasABoundedWaitAndCannotSendReplacement(){
        long id=source();decide(id);task(id);db.update("UPDATE oms_exchange SET platform_status='12',return_qc='PASSED' WHERE id=?",id);
        db.update("UPDATE oms_order_line SET refund_block_reason='平台退款 TEST 待审核' WHERE order_id=?",f.order);
        db.update("UPDATE oms_exchange_flow_task SET node='REFUND',wait_since=DATE_SUB(NOW(),INTERVAL 61 MINUTE) WHERE exchange_id=?",id);
        ExchangeFlowAutomation flow=flow();when(flow.returns.advance(anyString(),anyMap(),anyMap())).thenReturn(map("posted_quantity",2,"receipt_state","COMPLETED"));
        assertEquals("WAIT_REFUND_TIMEOUT",flow.step("VERIFY",id,1).get("code"));assertEquals("MANUAL",db.queryForObject("SELECT state FROM oms_exchange_flow_task WHERE exchange_id=?",String.class,id));verifyNoInteractions(flow.shipping);
    }
    @Test void explicitContinuationAuthorizationIsRequiredBeforeAutomaticRoundReview(){long id=source();decide(id);db.update("INSERT INTO oms_exchange_round(company_code,exchange_id,round_no,stock_reference,quantity,target_sku,state,recipient_json,basis_json,reason,evidence,actor) VALUES ('VERIFY',?,2,?,2,'B','REVIEW','{}','{}','merchant request','evidence','merchant')",id,"EXCHANGE:"+id+":2");assertThrows(IllegalArgumentException.class,()->decisions.continueRound("VERIFY",row(id),policy));verifyNoInteractions(decisions.continuations);}
    @Test void continuousExchangeSelectsActualReplacementSourceInsteadOfOriginalSalesSku(){
        db.update("UPDATE oms_order_shipment_line SET quantity=2,shipped_quantity=2 WHERE shipment_id=?",f.shipment);long first=source();decide(first);ExchangeFulfillment fulfillment=f.fulfillment();assertTrue(fulfillment.reserve("VERIFY",first));fulfillment.materialize("VERIFY",first);long actualB=f.shippedReplacement(first);
        Map<String,Object> next=f.source();next.put("dispute_id","223456");next.put("exchange_sku","A");long second=f.ingest(next);assertTrue(text(row(second),"problem_codes").contains("QUANTITY_MISMATCH"));decide(second);assertEquals("B",row(second).get("original_sku"));assertEquals("A",row(second).get("target_sku"));assertEquals(actualB,number(row(second),"source_shipment_line_id"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order",Integer.class));
    }
    @Test void platformSellerConsignedIsStillWaitingForFinalExchangeSuccess(){long id=source();decide(id);Map<String,Object> operation=journal.begin("VERIFY",row(id),"CONSIGN",policy,map("operation","CONSIGN"));db.update("UPDATE oms_exchange SET platform_status='13',platform_request=?,platform_operation='UNKNOWN' WHERE id=?",encode(map("operation","CONSIGN","flow_operation_id",operation.get("id"))),id);ExchangeExecution executor=f.executor(mock(ExchangeFulfillment.class));ReflectionTestUtils.setField(executor,"journal",journal);ReflectionTestUtils.invokeMethod(executor,"complete","VERIFY",id,"CONSIGN");assertEquals("PROCESSING",row(id).get("state"));assertEquals("PLATFORM_CONFIRMATION",row(id).get("stage"));assertEquals("SUCCESS",journal.records("VERIFY",id).get(0).get("state"));}
    @Test void concurrentAutomaticReviewsCannotConsumeSameShippedQuantityTwice() throws Exception {Map<String,Object> first=f.source();first.put("num",4);Map<String,Object> second=new LinkedHashMap<>(first);second.put("dispute_id","123457");long a=f.ingest(first),b=f.ingest(second);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Callable<Boolean> one=()->{start.await();try{decide(a);return true;}catch(IllegalArgumentException blocked){return false;}};Callable<Boolean> two=()->{start.await();try{decide(b);return true;}catch(IllegalArgumentException blocked){return false;}};Future<Boolean> x=pool.submit(one),y=pool.submit(two);start.countDown();assertNotEquals(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));assertEquals(4,db.queryForObject("SELECT SUM(requested_quantity) FROM oms_exchange WHERE approved_version IS NOT NULL",Integer.class));}finally{pool.shutdownNow();}}
}
